phase1.code:
use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    // ---- Basic Mutex ----
    let counter = Mutex::new(0);

    // ---- Locking and modifying ----
    {
        let mut num = counter.lock().unwrap();
        *num += 1;
        println!("Counter: {}", num);
    }  // lock is released here

    // ---- Mutex with Arc (shared ownership) ----
    let counter = Arc::new(Mutex::new(0));
    let mut handles = vec![];

    for _ in 0..10 {
        let counter = Arc::clone(&counter);
        let handle = thread::spawn(move || {
            let mut num = counter.lock().unwrap();
            *num += 1;
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    println!("Final counter: {}", *counter.lock().unwrap());

    // ---- Mutex with complex data ----
    #[derive(Debug)]
    struct Player {
        name: String,
        health: i32,
    }

    let players = Arc::new(Mutex::new(vec![
        Player { name: String::from("Hero"), health: 100 },
        Player { name: String::from("Aragorn"), health: 120 },
    ]));

    let players_clone = Arc::clone(&players);
    let handle = thread::spawn(move || {
        let mut list = players_clone.lock().unwrap();
        list.push(Player { name: String::from("Gandalf"), health: 80 });
    });
    handle.join().unwrap();

    {
        let list = players.lock().unwrap();
        println!("Players:");
        for p in list.iter() {
            println!("  {} (HP: {})", p.name, p.health);
        }
    }

    // ---- Mutex with guard ----
    let data = Mutex::new(vec![1, 2, 3]);

    // Lock and modify
    {
        let mut guard = data.lock().unwrap();
        guard.push(4);
        guard.push(5);
    }

    // Lock and read
    {
        let guard = data.lock().unwrap();
        println!("Data: {:?}", *guard);
    }

    // ---- Mutex with drop ----
    let m = Mutex::new(10);
    {
        let guard = m.lock().unwrap();
        println!("Locked: {}", *guard);
        // guard dropped here
    }

    // Now we can lock again
    let guard2 = m.lock().unwrap();
    println!("Locked again: {}", *guard2);
}

phase2.brokenCode:
use std::sync::Mutex;

fn main() {
    let counter = Mutex::new(0);
    let mut num = counter.lock().unwrap();
    *num += 1;
    // Forgot to drop the lock
    // Trying to lock again causes deadlock!
    let num2 = counter.lock().unwrap();  // Deadlock!
}

phase2.explanation:
The lock is not released because the guard is still in scope.

**The fix:**
```rust
{
    let mut num = counter.lock().unwrap();
    *num += 1;
}  // lock released here

let num2 = counter.lock().unwrap();
```

**Rust-chan says:**
"Locks are released when the guard is dropped. Use scopes to release locks."
